Metadados: https://apisidra.ibge.gov.br/metadata/{tabela}

Vamos tentar.

input.command:
foreach ($c in 49,85,45,123,62,57,80,127) {
  $u = "http://api.sidra.ibge.gov.br/values/t/5018/n1/all/v/all/p/2017/c$c/all?formato=json"
  try {
    $r = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 30
    $content = $r.Content
    if ($content -match '"D4N":"([^"]+)"') { $first = $matches[1] } else { $first = "N/A" }
    Write-Host "c$c => OK len=$($content.Length) first=$first"
  } catch {
    Write-Host "c$c => FAIL: $($_.Exception.Message)"
  }
}

$u = "http://api.sidra.ibge.gov.br/values/t/5018/n1/all/v/all/p/all/c696/all?formato=json"
try {
  $r = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 60
  $content = $r.Content
  $content | Out-File "C:\Users\Aluno\AppData\Local\Temp\opencode\t5018_all.json" -Encoding utf8
  Write-Host "OK len=$($content.Length)"
} catch {
  Write-Host "FAIL: $($_.Exception.Message)"
}

$tables = @(5018,5453,5925,5926,5465,5924,5466,5618)
foreach ($t in $tables) {
  try {
    $desc = Invoke-WebRequest -Uri "https://sidra.ibge.gov.br/ajax/tabela/descricao/1/$t" -UseBasicParsing -TimeoutSec 30
    $j = $desc.Content | ConvertFrom-Json
    $cls = $j.Classificacoes[0].Id
    $clsName = $j.Classificacoes[0].Nome
    Write-Host "Tabela $t : classificacao=$cls ($clsName)"
    # download
    $u = "http://api.sidra.ibge.gov.br/values/t/$t/n1/all/v/all/p/all/c$cls/all?formato=json"
    $r = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 120
    $r.Content | Out-File "C:\Users\Aluno\AppData\Local\Temp\opencode\t$t.json" -Encoding utf8
    Write-Host "   downloaded len=$($r.Content.Length)"
  } catch {
    Write-Host "Tabela $t FAIL: $($_.Exception.Message)"
  }
}

$tables = @(5453,5925,5926,5465,5924,5466,5618)
foreach ($t in $tables) {
  try {
    $u = "http://api.sidra.ibge.gov.br/values/t/$t/n1/all/v/all/p/all/c696/all?formato=json"
    $r = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 120 -Headers @{"User-Agent"="Mozilla/5.0"}
    $r.Content | Out-File "C:\Users\Aluno\AppData\Local\Temp\opencode\t$t.json" -Encoding utf8
    Write-Host "Tabela $t OK len=$($r.Content.Length)"
  } catch {
    Write-Host "Tabela $t FAIL: $($_.Exception.Message)"
  }
}

